  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C10"],
      "claim": "Apixaban, a high-transfer analogue, has an absolute oral bioavailability of approximately 66% in humans after oral administration, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Vernakalant under fasted conditions showed absolute oral bioavailability of 71 ± 21% in healthy volunteers, matching the fasted query condition and supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Brepocitinib had an estimated absolute bioavailability of 75% in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Selpercatinib showed a mean absolute bioavailability of 73% in volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Daridorexant had an absolute bioavailability of 62% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Papaverine from a sustained-release product had an absolute bioavailability of 22%, still above the 20% threshold and therefore supportive, though with a narrower margin.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "AZD0837 had an absolute bioavailability range of 22–55% in humans, supporting F >= 20%.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues report absolute oral bioavailability values at or above 22%, with most in the 50–75% range; no retrieved evidence falls below the 20% threshold. The fasted-state condition is directly supported by vernakalant data, and the overall evidence strongly favors high bioavailability.",
  "evidence_gaps": [
    "No direct experimental bioavailability measurement exists for the query molecule itself; the prediction relies on high-transfer analogues.",
    "Only one retrieved record explicitly reports fasted-state conditions, though other oral bioavailability values are not expected to be condition-dependent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

